INSERT INTO `wp_options` VALUES (491,'kalium_skin_custom_css','body {\n  background: #fff8ec;\n  color: #636444;\n}\ntable {\n  color: #777777;\n}\nh1 small,\nh2 small,\nh3 small,\nh4 small,\nh5 small,\nh6 small {\n  color: #777777;\n}\na {\n  color: #000000;\n}\na:focus,\na:hover {\n  color: #000000;\n}\n:focus {\n  color: #000000;\n}\n.wrapper {\n  background: #fff8ec;\n}\n.wrapper a:hover {\n  color: #000000;\n}\n.wrapper a:after {\n  background: #000000;\n}\n.site-footer a:hover {\n  color: #000000;\n}\n.product-filter ul li a:hover {\n  color: #000000;\n}\n.message-form .loading-bar {\n  background: #1a1a1a;\n}\n.message-form .loading-bar span {\n  background: #000000;\n}\n.skin--brand-primary {\n  color: #000000;\n}\n.btn.btn-primary {\n  background: #000000;\n}\n.btn.btn-primary:hover {\n  background: #000000;\n}\n.btn.btn-secondary {\n  background: #777777;\n}\n.btn.btn-secondary:hover {\n  background: #5e5e5e;\n}\n.site-footer .footer-bottom a {\n  color: #777777;\n}\n.site-footer .footer-bottom a:hover {\n  color: #000000;\n}\n.site-footer .footer-bottom a:after {\n  color: #000000;\n}\np {\n  color: #777777;\n}\n.section-title p {\n  color: #777777;\n}\n.section-title h1,\n.section-title h2,\n.section-title h3,\n.section-title h4,\n.section-title h5,\n.section-title h6 {\n  color: #636444;\n}\n.section-title h1 small,\n.section-title h2 small,\n.section-title h3 small,\n.section-title h4 small,\n.section-title h5 small,\n.section-title h6 small {\n  color: #777777 !important;\n}\n.blog-posts .isotope-item .box-holder .post-info {\n  border-color: #ffffff;\n}\n.blog-posts .box-holder .post-format .quote-holder {\n  background: #666666;\n}\n.blog-posts .box-holder .post-format .quote-holder blockquote {\n  color: #777777;\n}\n.blog-posts .box-holder .post-format .post-type {\n  background: #fff8ec;\n}\n.blog-posts .box-holder .post-format .post-type i {\n  color: #636444;\n}\n.blog-posts .box-holder .post-format .hover-state i {\n  color: #fff8ec;\n}\n.blog