INSERT INTO `wp_options` VALUES (995,'ls-google-fonts-data','a:2:{s:9:\"languages\";a:28:{i:0;a:2:{s:4:\"lang\";s:5:\"latin\";s:8:\"sentence\";s:27:\"It\'s just a matter of time.\";}i:1;a:2:{s:4:\"lang\";s:9:\"latin-ext\";s:8:\"sentence\";s:54:\"Qui trop légèrement se fie, mal à propos se défie.\";}i:2;a:2:{s:4:\"lang\";s:6:\"arabic\";s:8:\"sentence\";s:54:\"الحب سماء لا تمطر غير الأحلام.\";}i:3;a:2:{s:4:\"lang\";s:7:\"bengali\";s:8:\"sentence\";s:182:\"আগুনের শিখা নিভে গিয়েছিল, আর তিনি জানলা দিয়ে তারাদের দিকে তাকালেন৷\";}i:4;a:2:{s:4:\"lang\";s:16:\"chinese-hongkong\";s:8:\"sentence\";s:57:\"他們所有的設備和儀器彷彿都是有生命的。\";}i:5;a:2:{s:4:\"lang\";s:19:\"chinese-traditional\";s:8:\"sentence\";s:57:\"他们所有的设备和仪器彷佛都是有生命的。\";}i:6;a:2:{s:4:\"lang\";s:18:\"chinese-simplified\";s:8:\"sentence\";s:57:\"他們所有的設備和儀器彷彿都是有生命的。\";}i:7;a:2:{s:4:\"lang\";s:8:\"cyrillic\";s:8:\"sentence\";s:90:\"Алая вспышка осветила силуэт зазубренного крыла.\";}i:8;a:2:{s:4:\"lang\";s:12:\"cyrillic-ext\";s:8:\"sentence\";s:90:\"Алая вспышка осветила силуэт зазубренного крыла.\";}i:9;a:2:{s:4:\"lang\";s:10:\"devanagari\";s:8:\"sentence\";s:156:\"अंतरिक्ष यान से दूर नीचे पृथ्वी शानदार ढंग से जगमगा रही थी ।\";}i:10;a:2:{s:4:\"lang\";s:5:\"greek\";s:8:\"sentence\";s:42:\"Ήταν απλώς θέμα χρόνου.\";}i:11;a:2:{s:4:\"lang\";s:9:\"greek-ext\";s:8:\"sentence\";s:42:\"Ήταν απλώς θέμα χρόνου.\";}i:12;a:2:{s:4:\"lang\";s:8:\"gujarati\";s:8:\"sentence\";s:136:\"અમને તેની જાણ થાય તે પહેલાં જ, અમે જમીન છોડી દીધી હતી.\";}i:13;a:2:{s:4:\"lang\";s:8:\"gurmukhi\";s:8:\"sentence\";s:58:\"ਸਵਾਲ ਸਿਰਫ਼ ਸਮੇਂ ਦਾ ਸੀ।\";}i:14;a:2:{s:4:\"lang\";s:6:\"hebrew\";s:8:\"sentence\";s:63:\"אז הגיע הלילה של כוכב השביט הראשון.\";}i:15;a:2:{s:4:\"lang\";s:8:\"japanese\";s:8:\"sentence\";s:51:\"彼らの機器や装置はすべて生命体だ。\";}i:16;a:2:{s:4:\"lang\";s:7:\"kannada\";s:8:\"sentence\";s:76:\"ಇದು ಕೇವಲ ಸಮಯದ ಪ್ರಶ್ನೆಯಾಗಿದೆ.\";}i:17;a:2:{s:4:\"lang\";s:5:\"khmer\";s:8:\"sentence\";s:173:\"ខ្ញុំបានមើលព្យុះ ដែលមានភាពស្រស់ស្អាតណាស់ ប៉ុន្តែគួរឱ្យខ្លាច\";}i:18;a:2:{s:4:\"lang\";s:6:\"korean\";s:8:\"sentence\";s:51:\"그들의 장비와 기구는 모두 살아 있다.\";}i:19;a:2:{s:4:\"lang\";s:9:\"malayalam\";s:8:\"sentence\";s:187:\"അവരുടെ എല്ലാ ഉപകരണങ്ങളും യന്ത്രങ്ങളും ഏതെങ്കിലും രൂപത്തിൽ സജീവമാണ്.\";}i:20;a:2:{s:4:\"lang\";s:7:\"myanmar\";s:8:\"sentence\";s:163:\"သူတို့ရဲ့ စက်ပစ္စည်းတွေ၊ ကိရိယာတွေ အားလုံး အသက်ရှင်ကြတယ်။\";}i:21;a:2:{s:4:\"lang\";s:5:\"oriya\";s:8:\"sentence\";s:73:\"ଏହା କେବଳ ଏକ ସମୟ କଥା ହିଁ ଥିଲା.\";}i:22;a:2:{s:4:\"lang\";s:7:\"sinhala\";s:8:\"sentence\";s:96:\"එය කාලය පිළිබඳ ප්‍රශ්නයක් පමණක් විය.\";}i:23;a:2:{s:4:\"lang\";s:5:\"tamil\";s:8:\"sentence\";s:120:\"அந்திமாலையில், அலைகள் வேகமாக வீசத் தொடங்கின.\";}i:24;a:2:{s:4:\"lang\";s:6:\"telugu\";s:8:\"sentence\";s:120:\"ఆ రాత్రి మొదటిసారిగా ఒక నక్షత్రం నేలరాలింది.\";}i:25;a:2:{s:4:\"lang\";s:4:\"thai\";s:8:\"sentence\";s:72:\"การเดินทางขากลับคงจะเหงา\";}i:26;a:2:{s:4:\"lang\";s:7:\"tibetan\";s:8:\"sentence\";s:132:\"ཁོ་ཚོའི་སྒྲིག་ཆས་དང་ལག་ཆ་ཡོད་ཚད་གསོན་པོ་རེད།\";}i:27;a:2:{s:4:\"lang\";s:10:\"vietnamese\";s:8:\"sentence\";s:62:\"Bầu trời trong xanh thăm thẳm, không một gợn mây.\";}}s:5:\"fonts\";a:1722:{i:0;a:7:{s:6:\"family\";s:6:\"Roboto\";s:8:\"variants\";a:12:{i:0;s:3:\"100\";i:1;s:9:\"100italic\";i:2;s:3:\"300\";i:3;s:9:\"300italic\";i:4;s:7:\"regular\";i:5;s:6:\"italic\";i:6;s:3:\"500\";i:7;s:9:\"500italic\";i:8;s:3:\"700\";i:9;s:9:\"700italic\";i:10;s:3:\"900\";i:11;s:9:\"900italic\";}s:7:\"subsets\";a:7:{i:0;s:8:\"cyrillic\";i:1;s:12:\"cyrillic-ext\";i:2;s:5:\"greek\";i:3;s:9:\"greek-ext\";i:4;s:5:\"latin\";i:5;s:9:\"latin-ext\";i:6;s:10:\"vietnamese\";}s:7:\"version\";s:3:\"v32\";s:12:\"lastModified\";s:10:\"2024-09-04\";s:8:\"category\";s:10:\"sans-serif\";s:13:\"trendingIndex\";i:1288;}i:1;a:7:{s:6:\"family\";s:9:\"Open Sans\";s:8:\"variants\";a:12:{i:0;s:3:\"300\";i:1;s:7:\"regular\";i:2;s:3:\"500\";i:3;s:3:\"600\";i:4;s:3:\"700\";i:5;s:3:\"800\";i:6;s:9:\"300italic\";i:7;s:6:\"italic\";i:8;s:9:\"500italic\";i:9;s:9:\"600italic\";i:10;s:9:\"700italic\";i:11;s:9:\"800italic\";}s:7