INSERT INTO `wp_postmeta` VALUES (29317,4029,'page_custom_css','<script type=\"text/javascript\">\r\n    document.addEventListener(\'DOMContentLoaded\', function() {\r\n        // Check if it\'s the distribution page by looking for a specific class in the body\r\n        if (document.body.classList.contains(\'page-id-18\')) {\r\n            var links = document.querySelectorAll(\'.portfolio-item a.item-link\');\r\n            links.forEach(function(link) {\r\n                link.addEventListener(\'click\', function(e) {\r\n                    e.preventDefault(); // Prevent the link from navigating\r\n                });\r\n            });\r\n        }\r\n    });\r\n</script>\r\n');
