INSERT INTO `wp_postmeta` VALUES (35890,4066,'upper_content_desc','EyeSteelFilm is a film and interactive media company dedicated to using cinematic expression as a catalyst for social and political change. ');
INSERT INTO `wp_postmeta` VALUES (35891,4066,'_upper_content_desc','field_66c246e48ed40');
INSERT INTO `wp_postmeta` VALUES (35892,4066,'lower_content_desc','It was created to develop cinema that empowers people who are ignored by mainstream media, a mandate that has taken the company to explore projects, people and ideas around the world. For almost 20 years, Montreal’s award-winning EyeSteelFilm has made an international impact with social issue documentaries such as Twice Colonized (2023), Big Fight in Little Chinatown (2022), Midwives (2022), Softie (2020), Influence (2020), Dope is Death (2020), The Internet of Everything (2020), Anote’s Ark (2018), Let There be Light (2017), I am the Blues (2015), Deprogrammed (2015), Chameleon (2014), Forest of the Dancing Spirits (2013), Inside Lara Roxx (2011), Rip! A Remix Manifesto (2009), as well as a series of films chronicling modern life in China: Bone (2005), Chairman George (2006), Up the Yangtze (2007), Last Train Home (2009), Vanishing Spring Light (2011) and China Heavyweight, (2012). In the process, it has been the recipient of over 100 international awards.');
INSERT INTO `wp_postmeta` VALUES (35893,4066,'_lower_content_desc','field_66c2472f8ed41');
