INSERT INTO `wp_postmeta` VALUES (46584,4152,'synopsis_text','YINTAH, meaning “land” in the Wet’suwet’en language, tells the story of an Indigenous nation asserting sovereignty. It is the story of the Wet’suwet’en people reoccupying their territory and resisting the construction of multiple pipelines. The film follows Tsakë ze’ Howilhkat Freda Huson and Tsakë ze’ Sleydo’ Molly Wickham, along with the Wet’suwet’en Hereditary Chiefs and fellow land defenders, as they reoccupy and protect their traditional land in a decade-long battle to keep out the companies that seek to exploit it.');
INSERT INTO `wp_postmeta` VALUES (46585,4152,'_synopsis_text','field_66d8b9907cd13');
