INSERT INTO `wp_postmeta` VALUES (47186,4154,'press_quote_0_quote_content','The gorgeous sweeping vistas documented by this film’s enrapturing cinematography gives way to hellish images of strewn, chewed up land marked by apparent and invisible broken barriers ... Yintah vigorously paints a resiliency that will never surrender.');
INSERT INTO `wp_postmeta` VALUES (47187,4154,'_press_quote_0_quote_content','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (47188,4154,'press_quote_0_quote_source','Roger Ebert (True/False 2024: Ibelin, Alien Island, Yintah)');
INSERT INTO `wp_postmeta` VALUES (47189,4154,'_press_quote_0_quote_source','field_66f1dc032e0ec');
INSERT INTO `wp_postmeta` VALUES (47190,4154,'press_quote_1_quote_content','A poignant, powerful film unlike almost anything else you’ll see.');
INSERT INTO `wp_postmeta` VALUES (47191,4154,'_press_quote_1_quote_content','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (47192,4154,'press_quote_1_quote_source','The Grind');
INSERT INTO `wp_postmeta` VALUES (47193,4154,'_press_quote_1_quote_source','field_66f1dc032e0ec');
INSERT INTO `wp_postmeta` VALUES (47194,4154,'press_quote_2_quote_content','Yintah is a visceral, necessary, brilliantly executed film...a gripping and enduringly impactful experience deserving attention and recognition from all.');
INSERT INTO `wp_postmeta` VALUES (47195,4154,'_press_quote_2_quote_content','field_66f1dbee2e0eb');
