INSERT INTO `wp_postmeta` VALUES (51288,3891,'_upper_content_desc_en','field_66c246e48ed40');
INSERT INTO `wp_postmeta` VALUES (51289,3891,'upper_content_desc_fr','EyeSteelFilm est une société de cinéma et de médias interactifs qui se consacre à l\'utilisation de l\'expression cinématographique comme catalyseur de changement social et politique.');
INSERT INTO `wp_postmeta` VALUES (51290,3891,'_upper_content_desc_fr','field_670aa20da145d');
INSERT INTO `wp_postmeta` VALUES (51291,3891,'lower_content_desc_en','For almost 20 years, Montreal’s award-winning EyeSteelFilm has made an international impact with social issue documentaries such as Twice Colonized (2023), Big Fight in Little Chinatown (2022), Midwives (2022), Softie (2020), Influence (2020), Dope is Death (2020), The Internet of Everything (2020), Anote’s Ark (2018), Let There be Light (2017), I am the Blues (2015), Deprogrammed (2015), Chameleon (2014), Forest of the Dancing Spirits (2013), Inside Lara Roxx (2011), Rip! A Remix Manifesto (2009), as well as a series of films chronicling modern life in China: Bone (2005), Chairman George (2006), Up the Yangtze (2007), Last Train Home (2009), Vanishing Spring Light (2011) and China Heavyweight, (2012). In the process, it has been the recipient of over 100 international awards.');
INSERT INTO `wp_postmeta` VALUES (51292,3891,'_lower_content_desc_en','field_66c2472f8ed41');
INSERT INTO `wp_postmeta` VALUES (51293,3891,'lower_content_desc_fr','Depuis près de 20 ans, la société montréalaise primée EyeSteelFilm a eu un impact international avec des documentaires sur des enjeux sociaux tels que Twice Colonized (2023), Big Fight in Little Chinatown (2022), Midwives (2022), Softie (2020), Influence (2020). , Dope is Death (2020), The Internet of Everything (2020), Anote\'s Ark (2018), Que la lumière soit (2017), I am the Blues (2015), Deprogrammed (2015), Chameleon (2014), Forest of les esprits dansants (2013), Inside Lara Roxx (2011), Rip! A Remix Manifesto (2009), ainsi qu\'une série de films relatant la vie moderne en Chine : Bone (2005), Chairman George (2006), Up the Yangtze (2007), Last Train Home (2009), Vanishing Spring Light (2011). ) et China Heavyweight, (2012). Ce faisant, il a reçu plus de 100 prix internationaux.');
INSERT INTO `wp_postmeta` VALUES (51294,3891,'_lower_content_desc_fr','field_670aa21fa6da2');
