INSERT INTO `wp_postmeta` VALUES (51437,3901,'description_en','A Film Director plays a pivotal role in the filmmaking process. They collaborate with actors, read and develop scripts, and motivate the cast and crew to deliver their best performances. They also make critical decisions regarding set locations, budget management, and artistic execution.');
INSERT INTO `wp_postmeta` VALUES (51438,3901,'_description_en','field_66c2077a9fe71');
INSERT INTO `wp_postmeta` VALUES (51439,3901,'description_fr','Un réalisateur joue un rôle central dans le processus de réalisation d’un film. Ils collaborent avec des acteurs, lisent et développent des scénarios et motivent les acteurs et l\'équipe à offrir leurs meilleures performances. Ils prennent également des décisions critiques concernant les lieux de tournage, la gestion du budget et l\'exécution artistique.');
INSERT INTO `wp_postmeta` VALUES (51440,3901,'_description_fr','field_670aa634cc0d1');
