INSERT INTO `wp_postmeta` VALUES (52344,4215,'_press_quote_0_quote_source','field_66f1dc032e0ec');
INSERT INTO `wp_postmeta` VALUES (52345,4215,'press_quote_1_quote_content','A poignant, powerful film unlike almost anything else you’ll see.');
