INSERT INTO `wp_postmeta` VALUES (53105,3907,'press_quote_2_quote_content_en','Yintah is a visceral, necessary, brilliantly executed film...a gripping and enduringly impactful experience deserving attention and recognition from all.');
INSERT INTO `wp_postmeta` VALUES (53106,3907,'_press_quote_2_quote_content_en','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (53107,3907,'press_quote_2_quote_content_fr','Yintah est un film viscéral, nécessaire et brillamment exécuté... une expérience captivante et durablement percutante qui mérite l\'attention et la reconnaissance de tous.');
