INSERT INTO `wp_postmeta` VALUES (53393,4225,'press_quote_0_quote_content','The gorgeous sweeping vistas documented by this film’s enrapturing cinematography gives way to hellish images of strewn, chewed up land marked by apparent and invisible broken barriers ... Yintah vigorously paints a resiliency that will never surrender.');
INSERT INTO `wp_postmeta` VALUES (53394,4225,'_press_quote_0_quote_content','field_66f1dbee2e0eb');
