INSERT INTO `wp_postmeta` VALUES (53921,4226,'press_quote_0_quote_content_en','The gorgeous sweeping vistas documented by this film’s enrapturing cinematography gives way to hellish images of strewn, chewed up land marked by apparent and invisible broken barriers ... Yintah vigorously paints a resiliency that will never surrender. ❜');
INSERT INTO `wp_postmeta` VALUES (53922,4226,'_press_quote_0_quote_content_en','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (53923,4226,'press_quote_0_quote_content_fr','Les magnifiques vues panoramiques documentées par la cinématographie captivante de ce film cèdent la place à des images infernales de terres éparpillées et rongées, marquées par des barrières brisées apparentes et invisibles… Yintah peint vigoureusement une résilience qui ne cédera jamais. ❜');
INSERT INTO `wp_postmeta` VALUES (53924,4226,'_press_quote_0_quote_content_fr','field_670c2477ae1a4');
INSERT INTO `wp_postmeta` VALUES (53925,4226,'press_quote_1_quote_content_en','A poignant, powerful film unlike almost anything else you’ll see. ❜');
