INSERT INTO `wp_postmeta` VALUES (53927,4226,'press_quote_1_quote_content_fr','Un film poignant et puissant qui ne ressemble à presque rien d’autre que vous verrez. ❜');
INSERT INTO `wp_postmeta` VALUES (53928,4226,'_press_quote_1_quote_content_fr','field_670c2477ae1a4');
INSERT INTO `wp_postmeta` VALUES (53929,4226,'press_quote_2_quote_content_en','Yintah is a visceral, necessary, brilliantly executed film...a gripping and enduringly impactful experience deserving attention and recognition from all.');
INSERT INTO `wp_postmeta` VALUES (53930,4226,'_press_quote_2_quote_content_en','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (53931,4226,'press_quote_2_quote_content_fr','Yintah est un film viscéral, nécessaire et brillamment exécuté... une expérience captivante et durablement percutante qui mérite l\'attention et la reconnaissance de tous.');
