INSERT INTO `wp_postmeta` VALUES (54353,4228,'press_quote_0_quote_content_en','The gorgeous sweeping vistas documented by this film’s enrapturing cinematography gives way to hellish images of strewn, chewed up land marked by apparent and invisible broken barriers ... Yintah vigorously paints a resiliency that will never surrender. ❜');
INSERT INTO `wp_postmeta` VALUES (54354,4228,'_press_quote_0_quote_content_en','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (54355,4228,'press_quote_0_quote_content_fr','Les magnifiques vues panoramiques documentées par la cinématographie captivante de ce film cèdent la place à des images infernales de terres éparpillées et rongées, marquées par des barrières brisées apparentes et invisibles… Yintah peint vigoureusement une résilience qui ne cédera jamais. ❜');
INSERT INTO `wp_postmeta` VALUES (54356,4228,'_press_quote_0_quote_content_fr','field_670c2477ae1a4');
INSERT INTO `wp_postmeta` VALUES (54357,4228,'press_quote_1_quote_content_en','A poignant, powerful film unlike almost anything else you’ll see. ❜');
INSERT INTO `wp_postmeta` VALUES (54358,4228,'_press_quote_1_quote_content_en','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (54359,4228,'press_quote_1_quote_content_fr','Un film poignant et puissant qui ne ressemble à presque rien d’autre que vous verrez. ❜');
INSERT INTO `wp_postmeta` VALUES (54360,4228,'_press_quote_1_quote_content_fr','field_670c2477ae1a4');
INSERT INTO `wp_postmeta` VALUES (54361,4228,'press_quote_2_quote_content_en','Yintah is a visceral, necessary, brilliantly executed film...a gripping and enduringly impactful experience deserving attention and recognition from all.');
INSERT INTO `wp_postmeta` VALUES (54362,4228,'_press_quote_2_quote_content_en','field_66f1dbee2e0eb');
INSERT INTO `wp_postmeta` VALUES (54363,4228,'press_quote_2_quote_content_fr','Yintah est un film viscéral, nécessaire et brillamment exécuté... une expérience captivante et durablement percutante qui mérite l\'attention et la reconnaissance de tous.');
